package com.junshi.assistant;
import android.app.*;
import android.os.*;
import android.content.*;
import android.net.Uri;
import android.provider.Settings;
import android.widget.*;
import android.text.InputType;
import java.util.*;

public class MainActivity extends Activity {
 Session s; LinearLayout root,section; EditText server,user,password; TextView status;
 final Runnable listener=()->{if(status!=null)status.setText(s.status);};
 @Override public void onCreate(Bundle state){super.onCreate(state);s=(Session)getApplication();build();receive(new Intent(getIntent()));}
 void build(){ScrollView scroll=new ScrollView(this);root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);int pad=Theme.dp(this,12);root.setPadding(pad,pad,pad,pad);root.setClipChildren(false);Theme.background(root);scroll.setFillViewport(true);scroll.setClipToPadding(false);scroll.setOnApplyWindowInsetsListener((v,insets)->{v.setPadding(insets.getSystemWindowInsetLeft(),insets.getSystemWindowInsetTop(),insets.getSystemWindowInsetRight(),insets.getSystemWindowInsetBottom());return insets;});scroll.addView(root);setContentView(scroll);
 TextView title=new TextView(this);title.setText("AI 恋爱军师 · 随身助手");title.setTextSize(24);title.setTextColor(Theme.INK);title.setTypeface(null,android.graphics.Typeface.BOLD);root.addView(title);TextView subtitle=new TextView(this);subtitle.setText("把心里的话，聊得更自然。");subtitle.setTextColor(Theme.MUTED);subtitle.setPadding(0,0,0,Theme.dp(this,10));root.addView(subtitle);section=Theme.card(root,s.api==null?"连接与账号":"连接与管理");
 if(s.api==null){server=field("服务器 HTTPS 地址",getPreferences(0).getString("server","https://101.34.253.116"));user=field("用户名","");Theme.label(section,RegistrationRules.ACCOUNT_HINT,12);password=field("密码","");password.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);Theme.label(section,RegistrationRules.PASSWORD_HINT,12);LinearLayout login=row();Workspace.button(login,"登录",()->login(false));Workspace.button(login,"注册",()->login(true));}
 else {LinearLayout account=row();Workspace.button(account,"主页面 / 模型设置",()->openWeb());Workspace.button(account,"退出登录",()->{stopService(new Intent(this,OverlayService.class));s.logout();build();});
 LinearLayout manage=row();Workspace.button(manage,"新建人物与会话",()->createPerson());Workspace.button(manage,"添加平台账号",()->createPlatform());Workspace.button(manage,"刷新人物",s::loadPeople);
 root.addView(new Workspace(this));section=Theme.card(root,"附件与悬浮助手");LinearLayout tools=row();Workspace.button(tools,"图片 / 视频",()->{if(s.busy)return;Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("*/*");i.putExtra(Intent.EXTRA_MIME_TYPES,new String[]{"image/*","video/*"});i.putExtra(Intent.EXTRA_ALLOW_MULTIPLE,true);i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,7);});Workspace.button(tools,"开启悬浮小窗",()->overlay());Workspace.button(tools,"关闭小窗",()->stopService(new Intent(this,OverlayService.class)));}
 status=new TextView(this);status.setTextColor(Theme.MUTED);status.setTextSize(12);status.setPadding(Theme.dp(this,8),Theme.dp(this,8),Theme.dp(this,8),Theme.dp(this,8));root.addView(status);status.setText(s.status);}
 EditText field(String hint,String value){EditText e=new EditText(this);Theme.label(section,hint,13);e.setHint(hint);e.setText(value);section.addView(e);Theme.input(e);return e;}
 LinearLayout row(){LinearLayout r=new LinearLayout(this);section.addView(r);return r;}
 void login(boolean register){String base=server.getText().toString(),name=user.getText().toString(),pass=password.getText().toString();if(register){String error=RegistrationRules.error(name,pass);if(error!=null){s.message(error);return;}}s.run("正在连接…",()->{Api api=new Api(base,null);org.json.JSONObject result=api.object("POST",register?"/auth/register":"/auth/login",Api.json("username",name,"password",pass));return new Api(base,result.getString("access_token"));},api->{s.api=api;password.setText("");getPreferences(0).edit().putString("server",api.base).apply();build();s.loadPeople();});}
 void openWeb(){Api client=s.api;s.run("正在打开主页面…",()->client.object("POST","/auth/browser-handoff",null).getString("ticket"),ticket->{Intent i=new Intent(this,WebActivity.class);i.putExtra("origin",client.base);i.putExtra("ticket",ticket);startActivity(i);});}
 void overlay(){if(!Settings.canDrawOverlays(this)){startActivity(new Intent(Settings.ACTION_MANAGE_OVERLAY_PERMISSION,Uri.parse("package:"+getPackageName())));s.message("授权后返回，再点击开启悬浮小窗。");return;}if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)!=android.content.pm.PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{android.Manifest.permission.POST_NOTIFICATIONS},9);startForegroundService(new Intent(this,OverlayService.class));}
 void createPerson(){LinearLayout form=new LinearLayout(this);form.setOrientation(LinearLayout.VERTICAL);EditText name=new EditText(this),conversation=new EditText(this);name.setHint("人物名称");conversation.setHint("首个会话名称");form.addView(name);form.addView(conversation);new AlertDialog.Builder(this).setTitle("新建人物").setView(form).setNegativeButton("取消",null).setPositiveButton("创建",(d,w)->{String n=name.getText().toString().trim(),t=conversation.getText().toString().trim();if(n.isEmpty()||t.isEmpty()){s.message("请填写人物和会话名称。");return;}Api api=s.api;s.run("正在创建…",()->{String id=api.object("POST","/persons",Api.json("name",n)).getString("id");try{api.call("POST","/conversations",Api.json("person_id",id,"title",t));}catch(Exception e){throw new java.io.IOException("人物已创建，会话创建未完成，请在主页面核对后添加会话，避免重复创建人物。");}return api.array("/persons");},people->{s.people=people;s.message("人物与会话已创建，请选择人物。");});}).show();}
 void createPlatform(){if(s.person.isEmpty()){s.message("请先选择人物。");return;}LinearLayout f=new LinearLayout(this);f.setOrientation(LinearLayout.VERTICAL);Spinner p=new Spinner(this);String[] platforms={"wechat","douyin","tantan","momo","soul","other"};p.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,platforms));EditText handle=new EditText(this);handle.setHint("平台账号");f.addView(p);f.addView(handle);new AlertDialog.Builder(this).setTitle("添加平台账号").setView(f).setNegativeButton("取消",null).setPositiveButton("保存",(d,w)->{Api api=s.api;String id=s.person,h=handle.getText().toString().trim(),platform=platforms[p.getSelectedItemPosition()];if(h.isEmpty())return;s.run("正在保存平台账号…",()->{api.call("POST","/persons/"+id+"/platform-accounts",Api.json("platform",platform,"account_handle",h,"display_name",h));return api.array("/persons/"+id+"/platform-accounts");},a->{s.accounts=a;s.message("平台账号已保存；可在主页面绑定会话来源。");});}).show();}
 void receive(Intent i){if(i==null)return;if(s.busy){s.message("当前操作进行中，请完成后再次分享，原有草稿已保留。");return;}String a=i.getAction();if(!Intent.ACTION_SEND.equals(a)&&!Intent.ACTION_SEND_MULTIPLE.equals(a))return;CharSequence text=i.getCharSequenceExtra(Intent.EXTRA_TEXT);if(text!=null)s.editInput(text.toString());ArrayList<Uri> uris=new ArrayList<>();if(Intent.ACTION_SEND_MULTIPLE.equals(a)){ArrayList<Uri> list=i.getParcelableArrayListExtra(Intent.EXTRA_STREAM);if(list!=null)uris.addAll(list);}else{Uri uri=i.getParcelableExtra(Intent.EXTRA_STREAM);if(uri!=null)uris.add(uri);}importUris(uris);s.changed();}
 void importUris(List<Uri> uris){if(uris.isEmpty())return;if(s.busy||uris.size()+s.media.size()>4){s.message("每次最多 4 个附件，请等待当前操作完成。");return;}s.run("正在读取附件…",()->{List<Media> result=new ArrayList<>();try{for(Uri uri:uris)result.add(Media.copy(this,uri));return result;}catch(Exception e){for(Media m:result)m.file.delete();throw e;}},items->{s.media.addAll(items);s.job=null;s.message("附件已导入，请选择人物和会话。");});}
 @Override public void onNewIntent(Intent i){super.onNewIntent(i);receive(new Intent(i));}
 @Override public void onActivityResult(int req,int code,Intent i){super.onActivityResult(req,code,i);if(req==7&&code==RESULT_OK&&i!=null){List<Uri> uris=new ArrayList<>();if(i.getClipData()!=null)for(int n=0;n<i.getClipData().getItemCount();n++)uris.add(i.getClipData().getItemAt(n).getUri());else if(i.getData()!=null)uris.add(i.getData());importUris(uris);}}
 @Override protected void onStart(){super.onStart();s.listen(listener);}
 @Override protected void onStop(){s.unlisten(listener);super.onStop();}
}
